text:
{
  "title": "اتفاقية تقديم الخدمات ومعالجة البيانات",
  "planted": [
    {
      "slot": "p1",
      "text": "يحق للمزود استخدام البيانات المجمعة من خلال تقديم الخدمات لأي غرض تجاري تراه الإدارة مناسباً حالياً أو مستقبلاً، بما في ذلك تطوير منتجات جديدة واستخدامها لأغراض التسويق المباشر وتحليل السوق دون الحاجة إلى الحصول على موافقة مسبقة أو إشعار أصحاب البيانات بذلك."
    },
    {
      "slot": "p2",
      "text": "يلتزم المزود بإبلاغ الطرف الأول خطياً خلال مدة لا تتجاوز أربع وعشرين ساعة من تاريخ اكتشاف أي حادثة أمنية أو اختراق تقني أو وصول غير مرخص للبيانات، على أن يتولى الطرف الأول بعد ذلك إبلاغ الجهة التنظيمية المختصة وفقاً للإجراءات النظامية المتبعة."
    },
    {
      "slot": "p3",
      "text": "يتم الاحتفاظ بسجلات المعاملات المالية والفواتير المرتبطة بالعقود للمدة الزمنية التي تفرضها اللوائح الضريبية والمحاسبية والمالية ذات الصلة، بينما يتم التخلص من الوثائق الأخرى فور انتفاء الحاجة التشغيلية منها ودون إبطاء."
    }
  ],
  "neutral": [
    "تُعرّف الأتعاب بأنها المبالغ المالية المتفق عليها نظير تقديم الخدمات التقنية المحددة في جداول هذه الاتفاقية، وتستحق الدفع خلال ثلاثين يوماً من تاريخ استلام الفواتير النظامية المصدرة اصولياً.",
    "تبدأ هذه الاتفاقية اعتباراً من تاريخ توقيعها من الطرفين وتستمر لمدة سنة ميلادية كاملة، وتجدد تلقائياً لمثلها ما لم يقم أحد الطرفين بإشعار الطرف الآخر برغبته في عدم التجديد قبل موعد الانتهاء بشهرين على الأقل.",
    "لا يتحمل أي من الطرفين مسؤولية الأضرار غير المباشرة أو الخسائر التبعية أو فوات الأرباح الناتجة عن تنفيذ هذه الاتفاقية، وتحدد المسؤولية التعويضية القصوى بمجمل الأتعاب المدفوعة فعلياً خلال السنة التعوية الحالية.",
    "تخضع هذه الاتفاقية وتفسر وفقاً لأنظمة المملكة العربية السعودية، وتختص الجهات القضائية في مدينة الرياض بالنظر في أي نزاع قد ينشأ حول تفسير أو تنفيذ بنودها.",
    "تظل جميع حقوق الملكية الفكرية المرتبطة بالأنظمة والبرمجيات والأدوات المقدمة بموجب هذه الاتفاقية ملكاً خالصاً للمزود، ولا تمنح هذه الاتفاقية الطرف الثاني أي حقوق سوى حق الاستخدام المؤقت والمحدد بالغرض التشغيلي."
  ]
}
